import {mixerDefaults,mixerParameters,validAudioMixer,AudioMixerGraph} from './audio-mixer.js';
import {fileUrl} from './project-browser.js';
import {icon} from './icons.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class AudioMixerEditor {
  constructor(element,doc,hooks){this.element=element;this.doc=doc;this.hooks=hooks;this.selected=doc.view.mixerBus||'master';this.render();}
  edit(fn){try{const next=structuredClone(this.doc.data);fn(next);if(!validAudioMixer(next))throw Error('믹서 이름·경로·값을 확인하세요.');if(JSON.stringify(next)===JSON.stringify(this.doc.data)){this.render();return;}this.hooks.before();this.doc.data=next;this.hooks.change();if(this.graph){if(JSON.stringify(next.buses.map(b=>[b.id,b.parent]))!==JSON.stringify(this.graph.state.data.buses.map(b=>[b.id,b.parent])))this.stopPreview();else{this.graph.state.data=structuredClone(next);this.graph.state.base=structuredClone(next.buses);this.graph.update(0);}}this.render();}catch(e){this.hooks.error(e.message);this.render();}}
  async preview(){this.stopPreview();const epoch=this.previewEpoch;try{if(!this.previewClip)throw Error('미리보기 클립을 선택하세요.');this.context=new AudioContext();await this.context.resume();if(epoch!==this.previewEpoch)return;this.graph=new AudioMixerGraph(this.context,this.doc.data);this.player=new Audio(fileUrl(this.previewClip));this.player.loop=true;this.source=this.context.createMediaElementSource(this.player);this.source.connect(this.graph.input(this.selected));await this.player.play();if(epoch!==this.previewEpoch)return;this.meterTimer=setInterval(()=>{for(const [id,level] of Object.entries(this.graph?.levels()||{})){const meter=[...this.element.querySelectorAll('[data-mixer-meter]')].find(e=>e.dataset.mixerMeter===id);if(meter)meter.value=Math.min(1,level);}},80);this.render();}catch(e){if(epoch!==this.previewEpoch)return;this.stopPreview();this.hooks.error(e.message);}}
  stopPreview(){this.previewEpoch=(this.previewEpoch||0)+1;clearInterval(this.meterTimer);this.player?.pause();this.player=null;this.source?.disconnect();this.source=null;this.graph?.dispose();this.graph=null;this.context?.close().catch(()=>{});this.context=null;}
  commitInput(el){
    const next=structuredClone(this.doc.data),field=el.dataset.mixerField;
    if(el.dataset.mixerVolume){next.buses.find(b=>b.id===el.dataset.mixerVolume).volumeDb=Number(el.value);}
    else if(field)next.buses.find(b=>b.id===this.selected)[field]=el.type==='number'?Number(el.value):el.value;
    else if(el.dataset.mixerExposed!==undefined)next.exposed[Number(el.dataset.mixerExposed)].name=el.value;
    else if(el.dataset.mixerRenameSnapshot!==undefined)next.snapshots[Number(el.dataset.mixerRenameSnapshot)].name=el.value;
    else return;
    if(el.type==='number'&&el.value===''||!validAudioMixer(next))return;
    if(this.inputTransaction!==el){this.hooks.before();this.inputTransaction=el;}
    this.doc.data=next;this.hooks.change();if(this.graph){this.graph.state.data=structuredClone(next);this.graph.state.base=structuredClone(next.buses);this.graph.update(0);}
    if(el.dataset.mixerVolume)el.parentElement.querySelector('output').textContent=Number(el.value).toFixed(1)+' dB';
  }
  render(){
    this.inputTransaction=null;
    const data=this.doc.data,bus=data.buses.find(b=>b.id===this.selected)||data.buses[0];this.selected=bus.id;this.doc.view.mixerBus=bus.id;this.element.className='workspace-view audio-mixer-editor';
    const parents=new Set([bus.id]);let size;do{size=parents.size;for(const b of data.buses)if(parents.has(b.parent))parents.add(b.id);}while(size!==parents.size);
    const field=(key,label)=>{const [min,max]=mixerParameters[key];return `<label>${label}<input type="number" aria-label="믹서 ${label}" data-mixer-field="${key}" value="${bus[key]}" min="${min}" max="${max}" step="${['attack','release'].includes(key)?'.001':1}"><button data-mixer-expose="${key}" title="스크립트에 노출">${icon('link')}</button></label>`;};
    this.element.innerHTML=`<header class="document-toolbar"><strong>${icon('sound')} ${esc(data.name)}</strong><select aria-label="믹서 미리보기 클립" data-mixer-preview-clip><option value="">오디오 클립</option>${(this.hooks.files?.()||[]).filter(f=>f.kind==='media'&&/\.(wav|mp3|ogg|flac)$/i.test(f.path)).map(f=>`<option value="${esc(f.path)}" ${this.previewClip===f.path?'selected':''}>${esc(f.name)}</option>`).join('')}</select><button data-mixer-preview>${icon(this.player?'stop':'play')} ${this.player?'정지':'미리듣기'}</button><button data-mixer-add>${icon('plus')} 버스</button><button data-mixer-snapshot>${icon('camera')} 스냅샷 저장</button></header><div class="mixer-layout"><aside class="mixer-hierarchy"><h3>버스</h3>${data.buses.map(b=>`<button data-mixer-select="${esc(b.id)}" class="${b.id===bus.id?'selected':''}">${icon('sound')} ${esc(b.name)}<small>${esc(data.buses.find(p=>p.id===b.parent)?.name||'출력')}</small></button>`).join('')}<h3>스냅샷</h3>${data.snapshots.map((s,i)=>`<div class="mixer-snapshot"><input data-mixer-rename-snapshot="${i}" aria-label="스냅샷 이름 ${i+1}" value="${esc(s.name)}"><button data-mixer-apply="${i}" aria-label="${esc(s.name)} 적용">${icon('check')}</button><button data-mixer-delete-snapshot="${i}" aria-label="${esc(s.name)} 삭제">${icon('close')}</button></div>`).join('')}<h3>노출 파라미터</h3>${data.exposed.map((e,i)=>`<div class="mixer-exposed"><input aria-label="노출 이름 ${i+1}" data-mixer-exposed="${i}" value="${esc(e.name)}"><small>${esc(data.buses.find(b=>b.id===e.bus)?.name)} / ${e.parameter}</small><button data-mixer-unexpose="${i}" aria-label="노출 해제 ${i+1}">${icon('close')}</button></div>`).join('')}</aside><main class="mixer-strips">${data.buses.map(b=>`<section class="mixer-strip ${b.id===bus.id?'selected':''}" data-mixer-select="${esc(b.id)}"><header>${esc(b.name)}</header><div class="mixer-strip-controls">${[['mute','M'],['solo','S'],['bypass','FX']].map(([k,l])=>`<button data-mixer-toggle="${k}" data-mixer-bus="${esc(b.id)}" class="${b[k]?'active':''}" aria-pressed="${b[k]}" title="${k}">${l}</button>`).join('')}</div><meter min="0" max="1" value="0" data-mixer-meter="${esc(b.id)}" aria-label="${esc(b.name)} 신호 레벨"></meter><input type="range" min="-80" max="20" step=".1" value="${b.volumeDb}" data-mixer-volume="${esc(b.id)}" aria-label="${esc(b.name)} 볼륨"><output>${b.volumeDb.toFixed(1)} dB</output><small>${esc(data.buses.find(p=>p.id===b.parent)?.name||'오디오 출력')}</small></section>`).join('')}</main><aside class="mixer-details"><h3>${esc(bus.name)}</h3><section><label>이름<input aria-label="버스 이름" data-mixer-field="name" value="${esc(bus.name)}"></label><label>출력<select aria-label="버스 출력" data-mixer-field="parent" ${!bus.parent?'disabled':''}>${data.buses.filter(b=>!parents.has(b.id)).map(b=>`<option value="${esc(b.id)}" ${bus.parent===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label>${bus.parent?'<button data-mixer-remove>버스 삭제</button>':''}</section><section><h3>감쇠</h3>${field('volumeDb','볼륨')}</section><section><h3>필터</h3>${field('lowpass','로우패스 Hz')}${field('highpass','하이패스 Hz')}</section><section><h3>컴프레서</h3><label>활성화<input type="checkbox" data-mixer-field="compressor" aria-label="컴프레서 활성화" ${bus.compressor?'checked':''}></label>${field('threshold','임계 dB')}${field('ratio','압축비')}${field('attack','어택 초')}${field('release','릴리스 초')}</section></aside></div>`;
    this.element.onclick=e=>{const b=e.target.closest('button'),strip=e.target.closest('[data-mixer-select]');if(b?.hasAttribute('data-mixer-preview')){if(this.player){this.stopPreview();this.render();}else this.preview();}else if(b?.hasAttribute('data-mixer-add'))this.edit(d=>{let i=1;while(d.buses.some(b=>b.name==='Bus '+i))i++;const id=crypto.randomUUID();d.buses.push({id,name:'Bus '+i,parent:this.selected,...mixerDefaults});for(const s of d.snapshots)s.values[id]={...mixerDefaults};this.selected=id;});else if(b?.hasAttribute('data-mixer-remove'))this.edit(d=>{const gone=d.buses.find(b=>b.id===this.selected);for(const b of d.buses)if(b.parent===gone.id)b.parent=gone.parent;d.buses=d.buses.filter(b=>b.id!==gone.id);d.exposed=d.exposed.filter(e=>e.bus!==gone.id);for(const s of d.snapshots)delete s.values[gone.id];this.selected=gone.parent;});else if(b?.dataset.mixerToggle)this.edit(d=>{const bus=d.buses.find(x=>x.id===b.dataset.mixerBus);bus[b.dataset.mixerToggle]=!bus[b.dataset.mixerToggle];});else if(b?.hasAttribute('data-mixer-snapshot'))this.edit(d=>{let i=1;while(d.snapshots.some(s=>s.name==='Snapshot '+i))i++;d.snapshots.push({name:'Snapshot '+i,values:Object.fromEntries(d.buses.map(b=>[b.id,Object.fromEntries(Object.keys(mixerDefaults).map(k=>[k,b[k]]))]))});});else if(b?.dataset.mixerApply!==undefined)this.edit(d=>{const snapshot=d.snapshots[Number(b.dataset.mixerApply)];for(const b of d.buses)Object.assign(b,snapshot.values[b.id]);});else if(b?.dataset.mixerDeleteSnapshot!==undefined)this.edit(d=>d.snapshots.splice(Number(b.dataset.mixerDeleteSnapshot),1));else if(b?.dataset.mixerExpose)this.edit(d=>{const key=b.dataset.mixerExpose;if(d.exposed.some(e=>e.bus===this.selected&&e.parameter===key))return;let name=bus.name.replaceAll(' ','')+'_'+key,i=1;while(d.exposed.some(e=>e.name===name))name=bus.name.replaceAll(' ','')+'_'+key+i++;d.exposed.push({name,bus:this.selected,parameter:key});});else if(b?.dataset.mixerUnexpose!==undefined)this.edit(d=>d.exposed.splice(Number(b.dataset.mixerUnexpose),1));else if(strip&&!e.target.closest('input,meter,output')){this.selected=strip.dataset.mixerSelect;this.render();}};
    this.element.onchange=e=>{const el=e.target;if(el.hasAttribute('data-mixer-preview-clip'))this.previewClip=el.value;else if(el.dataset.mixerField)this.edit(d=>d.buses.find(b=>b.id===this.selected)[el.dataset.mixerField]=el.type==='number'?Number(el.value):el.type==='checkbox'?el.checked:el.value);else if(el.dataset.mixerVolume)this.edit(d=>d.buses.find(b=>b.id===el.dataset.mixerVolume).volumeDb=Number(el.value));else if(el.dataset.mixerExposed!==undefined)this.edit(d=>d.exposed[Number(el.dataset.mixerExposed)].name=el.value);};
    this.element.oninput=e=>this.commitInput(e.target);this.element.onfocusout=e=>{if(this.inputTransaction===e.target)this.inputTransaction=null;};
  }
  dispose(){this.stopPreview();}
}
